// src/lib/rechner/annahmen.js
//
// Formatierung für alle Rechner. Die fachlichen Marktannahmen stehen in
// src/lib/invest/markt.js – hier nur Zahlenformate (de-DE).

export { STAND } from "../invest/markt.js";

export const fmt = (n, stellen = 0) =>
  Number.isFinite(n) ? n.toLocaleString("de-DE", { minimumFractionDigits: stellen, maximumFractionDigits: stellen }) : "–";
export const fmtEur = (n) => `${fmt(Math.round(n))} €`;
export const fmtMio = (n, stellen = 1) => `${fmt(n / 1e6, stellen)} Mio. €`;
export const fmtPct = (n, stellen = 1) => `${fmt(n * 100, stellen)} %`;
export const fmtCt = (n, stellen = 1) => `${fmt(n, stellen)} ct/kWh`;
// src/lib/rechner/pacht.js
//
// Pachtrechner für Freiflächen-PV – reine Funktionen, ohne React.
// Alle Marktannahmen aus src/lib/invest/markt.js.

import { ERLOESE, FREIFLAECHE, PACHT, regionById, laenderSperre, eegErloesCt } from "../invest/markt.js";

/** Kurzbezeichnungen der Regionen für enge Auswahlfelder */
export const REGION_KURZ = { "de-nord": "Nord-DE", "de-ost": "Ost-DE", "de-west": "West-DE", "de-sued": "Süd-DE", at: "Österreich", ch: "Schweiz" };

export const PACHTMODELLE = [
  { id: "fest", label: "Festpacht", sub: "€/ha, gleichbleibend" },
  { id: "index", label: "Indexiert", sub: "€/ha + Inflation" },
  { id: "umsatz", label: "Umsatz", sub: "% der Stromerlöse" },
];

/** Leistung (kWp) und Jahresertrag (kWh) eines Solarparks auf `ha` Hektar */
export function parkAuf(ha, regionId) {
  const region = regionById(regionId);
  const kwp = (ha / FREIFLAECHE.haProMwp) * 1000;
  return { kwp, kwh: kwp * region.ertrag, region };
}

/**
 * Pacht über die Laufzeit.
 *
 * eingaben:
 *  ha, regionId, modell (fest|index|umsatz), proHa (€/ha·a), umsatzAnteil (0–1),
 *  mindestProHa (Mindestpacht bei Umsatzmodell, €/ha·a), laufzeit (Jahre),
 *  ackerProHa (heutige Ackerpacht €/ha·a), dbProHa (Deckungsbeitrag Eigenbewirtschaftung €/ha·a),
 *  vorlaufJahre (Jahre bis Baubeginn mit Reservierungsprämie), reservierungProHa (€/ha·a)
 *
 * Rückgabe: Jahresreihen (kumuliert) für Solarpacht, Ackerpacht, Deckungsbeitrag und Kennzahlen.
 */
export function pachtRechnung({
  ha = 10,
  regionId = "de-sued",
  modell = "fest",
  proHa = PACHT.freiflaecheProHa.mittel,
  umsatzAnteil = 0.06,
  mindestProHa = PACHT.freiflaecheProHa.min,
  laufzeit = PACHT.laufzeit,
  ackerProHa = PACHT.ackerProHa,
  dbProHa = PACHT.deckungsbeitragAcker.mittel,
  vorlaufJahre = 0,
  reservierungProHa = PACHT.reservierungProHa.min,
} = {}) {
  const { kwp, kwh, region } = parkAuf(ha, regionId);
  const jahre = [];
  let sumSolar = 0;
  let sumAcker = 0;
  let sumDb = 0;
  const gesamtJahre = vorlaufJahre + laufzeit;

  for (let j = 1; j <= gesamtJahre; j++) {
    const betrieb = j > vorlaufJahre;
    const t = j - vorlaufJahre - 1; // Betriebsjahr ab 0
    let solar;
    let strom = 0;
    if (!betrieb) {
      // Vor Baubeginn: Reservierungsprämie – die Fläche wird weiter bewirtschaftet
      solar = ha * reservierungProHa;
    } else if (modell === "umsatz") {
      // EEG-Phase mit § 51 EEG (negative Zeiträume ohne Marktprämie, markt.js eegErloesCt), danach Marktwert
      const markt = ERLOESE.merchantCt * Math.pow(1 + (ERLOESE.merchantSteigerung || 0), t);
      const ct = t < 20 ? eegErloesCt(ERLOESE.eegFreiflaecheCt, markt) : markt;
      strom = kwh * Math.pow(1 - FREIFLAECHE.degradation, t) * (ct / 100);
      solar = Math.max(strom * umsatzAnteil, ha * mindestProHa);
    } else if (modell === "index") {
      solar = ha * proHa * Math.pow(1 + PACHT.indexierung, t);
    } else {
      solar = ha * proHa;
    }
    // Vergleich: Ackerpacht und Deckungsbeitrag steigen vereinfacht mit derselben Indexierung
    const f = Math.pow(1 + PACHT.indexierung, j - 1);
    const acker = ha * ackerProHa * f;
    // Vor Baubeginn bewirtschaftet der Eigentümer weiter: Deckungsbeitrag kommt zur Prämie hinzu
    const db = ha * dbProHa * f;
    const solarGesamt = betrieb ? solar : solar + db;
    sumSolar += solarGesamt;
    sumAcker += acker;
    sumDb += db;
    jahre.push({ jahr: j, betrieb, solar: solarGesamt, acker, db, strom, sumSolar, sumAcker, sumDb });
  }

  const erstesBetriebsjahr = jahre.find((x) => x.betrieb) || jahre[0];
  return {
    /** Länder-Sperre AT/CH: €-Pacht, DE-Ackerpacht und EEG-Umsatzmodell gelten nur für DE (markt.js LAENDER_SPERRE) */
    sperre: laenderSperre(region.land),
    kwp,
    kwh,
    region,
    jahre,
    ersteJahrespacht: erstesBetriebsjahr.solar,
    proHaErstesJahr: erstesBetriebsjahr.solar / ha,
    summeSolar: sumSolar,
    summeAcker: sumAcker,
    summeDb: sumDb,
    faktorAcker: sumAcker > 0 ? sumSolar / sumAcker : null,
    faktorDb: sumDb > 0 ? sumSolar / sumDb : null,
    durchschnitt: sumSolar / gesamtJahre,
    mehrGgAcker: sumSolar - sumAcker,
    mehrGgDb: sumSolar - sumDb,
  };
}
// src/lib/rechner/kommune.js
//
// Was ein Solarpark der Standortgemeinde bringt – reine Logik (Deutschland).
// Quellen der Einnahmen:
//  1. § 6 EEG: freiwillige Zahlung des Betreibers bis 0,2 ct/kWh
//  2. Gewerbesteuer: 90 % des Messbetrags an die Standortgemeinde
//     (§ 29 Abs. 1 Nr. 2 GewStG), 100 %, wenn der Betreiber dort seinen Sitz hat
//  3. Pacht, wenn Flächen der Gemeinde genutzt werden
//
// Die Gewerbesteuer wird vereinfacht aus der Solarpark-Rechnung abgeleitet:
// Ergebnis = EBITDA − lineare AfA − Zinsen, Hinzurechnung von 25 % der Zinsen
// über 200.000 €, Verlustvortrag ohne Mindestbesteuerung. Typisch ist, dass in
// den ersten Jahren durch Abschreibung und Zinsen kaum Gewerbesteuer anfällt.

import { KOMMUNE, BAUART, PACHT, ERLOESE, FREIFLAECHE, laenderSperre } from "../invest/markt.js";
import { rechneSolarpark } from "./solarpark.js";

export const STANDARD = {
  mwp: 20,
  regionId: "de-sued",
  bauart: "sued",
  hebesatz: KOMMUNE.hebesatz,
  paragraph6: true,
  gemeindeflaeche: false,
  anteilGemeinde: 1,
  pachtHa: PACHT.freiflaecheProHa.mittel,
  sitzInGemeinde: false,
  /** Erlös des Parks in ct/kWh (EEG-Zuschlag bzw. PPA) – bestimmt den Gewinn und damit die Gewerbesteuer */
  preisCt: ERLOESE.eegFreiflaecheCt,
};

export function rechneKommune(eingabe = {}) {
  const e = { ...STANDARD, ...eingabe };
  const N = KOMMUNE.betrachtungJahre;
  const L = FREIFLAECHE.laufzeit; // gesamte Laufzeit – nach Ende der AfA steigt die Gewerbesteuer
  const park = rechneSolarpark({ mwp: e.mwp, regionId: e.regionId, bauart: e.bauart, pachtHa: e.pachtHa, preisCt: e.preisCt, modell: "eeg", laufzeit: L });
  const flaecheHa = e.mwp * (BAUART[e.bauart] || BAUART.sued).haProMwp;
  const afa = park.investition.summe / KOMMUNE.afaJahre;
  const anteilGewSt = e.sitzInGemeinde ? 1 : KOMMUNE.gewerbesteuerStandort;

  let verlustvortrag = 0;
  const jahre = [];
  for (let t = 1; t <= L; t++) {
    const j = park.jahre[t - 1];
    // § 6 Abs. 5 EEG: Erstattet wird nur für Strommengen, für die eine Förderung nach dem EEG in Anspruch genommen
    // wurde (gesetze-im-internet.de/eeg_2014/__6.html, abgerufen 03.10.2026). Paket E: Zahlung daher nur in der
    // EEG-Förderphase (vorher alle 30 Jahre) und ohne die nach § 51 EEG nicht geförderten Zeiträume (vorher volle Erzeugung).
    const p6 = e.paragraph6 && j.imVertrag ? (j.erzeugung * j.vergueteterAnteil * KOMMUNE.beteiligungCt) / 100 : 0;
    // § 6-Zahlung ist beim Betreiber Betriebsausgabe (Erstattung durch den Netzbetreiber bei EEG-Anlagen – vereinfacht neutral)
    const ergebnis = j.ebitda - (t <= KOMMUNE.afaJahre ? afa : 0) - j.zinsen;
    const hinzurechnung = Math.max(0, j.zinsen - KOMMUNE.hinzurechnungFreibetrag) * KOMMUNE.hinzurechnungZinsen;
    let ertrag = ergebnis + hinzurechnung;
    if (ertrag < 0) {
      verlustvortrag += -ertrag;
      ertrag = 0;
    } else if (verlustvortrag > 0) {
      const verrechnet = Math.min(verlustvortrag, ertrag);
      verlustvortrag -= verrechnet;
      ertrag -= verrechnet;
    }
    const gewSt = ertrag * KOMMUNE.messzahl * e.hebesatz * anteilGewSt;
    const pacht = e.gemeindeflaeche ? flaecheHa * e.anteilGemeinde * e.pachtHa * Math.pow(1 + PACHT.indexierung, t - 1) : 0;
    jahre.push({ jahr: t, p6, gewSt, pacht, summe: p6 + gewSt + pacht, erzeugung: j.erzeugung });
  }
  const summeBis = (k, bis) => jahre.slice(0, bis).reduce((s, j) => s + j[k], 0);
  const topf = (bis) => {
    const g = { p6: summeBis("p6", bis), gewSt: summeBis("gewSt", bis), pacht: summeBis("pacht", bis) };
    g.summe = g.p6 + g.gewSt + g.pacht;
    return g;
  };
  const gesamt = topf(N);
  const gesamtLaufzeit = topf(L);
  const ersteGewSt = jahre.find((j) => j.gewSt > 0)?.jahr ?? null;
  const spaet = jahre.slice(KOMMUNE.afaJahre);
  const gewStNachAfa = spaet.length ? spaet.reduce((s, j) => s + j.gewSt, 0) / spaet.length : 0;

  return {
    eingabe: e,
    /** Länder-Sperre AT/CH: § 6 EEG und Gewerbesteuer sind deutsches Recht (markt.js LAENDER_SPERRE) */
    sperre: laenderSperre(e.regionId),
    /** Hinweis: Landesgesetze zur Beteiligung (KOMMUNE.laenderMitBeteiligungsgesetz) sind nicht gerechnet */
    landesregeln: { laender: KOMMUNE.laenderMitBeteiligungsgesetz, stand: KOMMUNE.laenderGesetzeStand, gerechnet: false },
    jahre,
    gesamt,
    gesamtLaufzeit,
    gewStNachAfa,
    proJahr: gesamt.summe / N,
    jahre1: jahre[0],
    ersteGewSt,
    flaecheHa,
    ertragJahr1: park.ertragJahr1,
    investition: park.investition.summe,
    N,
    L,
  };
}

/* ------------------------------------------------------------------ */
/* Selbsttest: node src/lib/rechner/kommune.js                         */
/* ------------------------------------------------------------------ */

export function selbsttest() {
  const fehler = [];
  const pruefe = (ok, text) => {
    if (!ok) fehler.push(text);
  };
  const r = rechneKommune({ mwp: 10, regionId: "de-sued", paragraph6: true, gemeindeflaeche: false });
  const anteil51 = 1 - ERLOESE.paragraph51.anteilNegativ;
  pruefe(Math.abs(r.jahre[0].p6 - 11_000_000 * anteil51 * 0.002) < 1, "§ 6: 11 GWh × geförderter Anteil (§ 51) × 0,2 ct");
  pruefe(r.jahre[19].p6 > 0 && r.jahre[20].p6 === 0, "§ 6 nur in der EEG-Förderphase (Erstattung § 6 Abs. 5)");
  pruefe(rechneKommune({ regionId: "at" }).sperre?.land === "AT" && r.sperre === null, "Länder-Sperre: AT gesperrt, DE frei");
  pruefe(r.jahre.length === 30, "30 Jahre Laufzeit gerechnet");
  pruefe(r.gesamt.pacht === 0, "ohne Gemeindefläche keine Pacht");
  pruefe(r.gesamtLaufzeit.gewSt > 0, "über die Laufzeit fällt Gewerbesteuer an");
  pruefe(r.jahre[0].gewSt <= r.jahre[24].gewSt, "Gewerbesteuer steigt tendenziell (AfA, Zinsen, Verlustvortrag)");
  pruefe(r.gewStNachAfa > 0, "nach Ende der AfA fällt Gewerbesteuer an");
  const teuer = rechneKommune({ mwp: 10, preisCt: 6.5 });
  pruefe(teuer.gesamt.gewSt > r.gesamt.gewSt, "höherer Erlös → mehr Gewerbesteuer");
  const ohne6 = rechneKommune({ mwp: 10, paragraph6: false });
  pruefe(ohne6.gesamt.p6 === 0, "ohne § 6 keine Zahlung");
  const hoch = rechneKommune({ mwp: 10, hebesatz: 5 });
  const niedrig = rechneKommune({ mwp: 10, hebesatz: 3 });
  pruefe(Math.abs(hoch.gesamtLaufzeit.gewSt / niedrig.gesamtLaufzeit.gewSt - 5 / 3) < 1e-6, "Gewerbesteuer proportional zum Hebesatz");
  const sitz = rechneKommune({ mwp: 10, sitzInGemeinde: true });
  pruefe(Math.abs(sitz.gesamtLaufzeit.gewSt / r.gesamtLaufzeit.gewSt - 1 / 0.9) < 1e-6, "Sitz in der Gemeinde: 100 statt 90 %");
  const flaeche = rechneKommune({ mwp: 10, gemeindeflaeche: true, anteilGemeinde: 1, pachtHa: 2000 });
  pruefe(Math.abs(flaeche.jahre[0].pacht - 11 * 2000) < 1, "Pacht: 11 ha × 2.000 €");
  return { fehler, beispiel: r };
}

if (typeof process !== "undefined" && process.argv?.[1] && /kommune\.js$/.test(process.argv[1].replace(/\\/g, "/"))) {
  const { fehler, beispiel: r } = selbsttest();
  console.log(
    `Beispiel 10 MWp: § 6 ${Math.round(r.gesamt.p6)} €, GewSt ${Math.round(r.gesamt.gewSt)} € (erstmals Jahr ${r.ersteGewSt}, danach ~${Math.round(r.gewStNachAfa)} €/J.), gesamt ${Math.round(r.gesamt.summe)} € in 20 J., ${Math.round(r.gesamtLaufzeit.summe)} € in 30 J.`
  );
  if (fehler.length) {
    console.error("FEHLER:\n- " + fehler.join("\n- "));
    process.exit(1);
  }
  console.log("Selbsttest kommune.js: alle Prüfungen bestanden.");
}
// test/charakterisierung/rechner.test.mjs
//
// Golden-Master-Vergleich: heutige Rechner-Ausgaben gegen die eingecheckten Snapshots.
//   node --test test/charakterisierung/rechner.test.mjs
// Snapshots bewusst neu schreiben (nur mit Begründung im PR, siehe README):
//   npm run test:snapshots:aktualisieren
// Lesbarer Abweichungsbericht (Markdown) für den PR:
//   npm run test:snapshots:diff

import test from "node:test";
import assert from "node:assert/strict";
import { RECHNER } from "./faelle.mjs";
import { abweichungen, aktuelleAusgaben, leseSnapshot } from "./snapshot.mjs";

for (const name of Object.keys(RECHNER)) {
  test(`Charakterisierung ${name}`, async (t) => {
    const snap = leseSnapshot(name);
    assert.ok(snap, `Kein Snapshot für ${name} – erst „npm run test:snapshots:aktualisieren“ ausführen.`);
    const jetzt = await aktuelleAusgaben(name);
    const faelle = new Set([...Object.keys(snap.faelle), ...Object.keys(jetzt.faelle)]);
    for (const fall of faelle) {
      await t.test(fall, () => {
        assert.ok(fall in snap.faelle, `Fall „${fall}“ ist neu – Snapshot aktualisieren.`);
        assert.ok(fall in jetzt.faelle, `Fall „${fall}“ fehlt in faelle.mjs, steht aber im Snapshot.`);
        const diff = abweichungen(snap.faelle[fall], jetzt.faelle[fall]);
        if (diff.length) {
          const zeilen = diff.slice(0, 25).map((d) => `  ${d.pfad}: ${d.alt} → ${d.neu}`);
          if (diff.length > 25) zeilen.push(`  … und ${diff.length - 25} weitere`);
          assert.fail(`${name}/${fall}: ${diff.length} Abweichung(en) gegenüber dem Snapshot\n${zeilen.join("\n")}`);
        }
      });
    }
  });
}
// test/charakterisierung/snapshot.mjs
//
// Stabile Serialisierung und Vergleich der Rechner-Ausgaben (ohne Abhängigkeiten).
//  - Zahlen auf 12 signifikante Stellen (Gleitkomma-Rauschen zwischen Plattformen
//    soll keinen Diff erzeugen, echte Wertänderungen schon)
//  - NaN/Infinity/undefined/Funktionen als lesbare Marker, damit auch sie im Diff stehen
//  - Objektschlüssel sortiert (stabile Dateien, kleine Diffs)

import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { RECHNER } from "./faelle.mjs";

const HIER = dirname(fileURLToPath(import.meta.url));
export const WURZEL = resolve(HIER, "..", "..");
export const SNAPSHOT_ORDNER = join(HIER, "snapshots");

export function normalisiere(wert, gesehen = new WeakSet()) {
  if (typeof wert === "number") {
    if (Number.isNaN(wert)) return "§NaN";
    if (!Number.isFinite(wert)) return wert > 0 ? "§Infinity" : "§-Infinity";
    if (Object.is(wert, -0) || wert === 0) return 0;
    return Number(wert.toPrecision(12));
  }
  if (wert === undefined) return "§undefined";
  if (typeof wert === "function") return "§Funktion";
  if (typeof wert === "bigint") return `§BigInt:${wert}`;
  if (typeof wert === "symbol") return `§${String(wert)}`;
  if (wert === null || typeof wert !== "object") return wert;
  if (wert instanceof Date) return `§Date:${Number.isNaN(wert.getTime()) ? "ungültig" : wert.toISOString()}`;
  if (gesehen.has(wert)) return "§Zirkel";
  gesehen.add(wert);
  let aus;
  if (Array.isArray(wert)) aus = wert.map((v) => normalisiere(v, gesehen));
  else if (wert instanceof Map) aus = { "§Map": [...wert.entries()].map(([k, v]) => [normalisiere(k, gesehen), normalisiere(v, gesehen)]) };
  else if (wert instanceof Set) aus = { "§Set": [...wert].map((v) => normalisiere(v, gesehen)) };
  else {
    aus = {};
    for (const k of Object.keys(wert).sort()) aus[k] = normalisiere(wert[k], gesehen);
  }
  gesehen.delete(wert); // geteilte (nicht zirkuläre) Referenzen erlaubt
  return aus;
}

/** Führt einen Fall aus; ein Wurf wird als Ergebnis festgehalten (auch das ist Verhalten). */
export function fuehreAus(fn, modul) {
  try {
    return normalisiere(fn(modul));
  } catch (e) {
    return { "§wirft": String(e?.message || e) };
  }
}

export async function ladeModul(relPfad) {
  return import(pathToFileURL(join(WURZEL, relPfad)).href);
}

/** Aktuelle Ausgaben eines Rechners (alle Fälle). */
export async function aktuelleAusgaben(name) {
  const r = RECHNER[name];
  const m = await ladeModul(r.modul);
  const faelle = {};
  for (const [fall, fn] of Object.entries(r.faelle)) faelle[fall] = fuehreAus(fn, m);
  return { rechner: name, modul: r.modul, faelle };
}

export const snapshotPfad = (name) => join(SNAPSHOT_ORDNER, `${name}.json`);

export function leseSnapshot(name) {
  const p = snapshotPfad(name);
  if (!existsSync(p)) return null;
  return JSON.parse(readFileSync(p, "utf8"));
}

export function schreibeSnapshot(name, daten) {
  mkdirSync(SNAPSHOT_ORDNER, { recursive: true });
  writeFileSync(snapshotPfad(name), JSON.stringify(daten, null, 1) + "\n", "utf8");
}

const kurz = (v) => {
  const s = JSON.stringify(v);
  return s === undefined ? "–" : s.length > 80 ? s.slice(0, 77) + "…" : s;
};

/** Liste der Abweichungen { pfad, alt, neu } zwischen zwei normalisierten Werten. */
export function abweichungen(alt, neu, pfad = "", liste = []) {
  if (alt === neu) return liste;
  const istObj = (v) => v !== null && typeof v === "object";
  if (istObj(alt) && istObj(neu) && Array.isArray(alt) === Array.isArray(neu)) {
    const schluessel = new Set([...Object.keys(alt), ...Object.keys(neu)]);
    for (const k of schluessel) {
      const p = Array.isArray(alt) ? `${pfad}[${k}]` : pfad ? `${pfad}.${k}` : k;
      if (!(k in alt)) liste.push({ pfad: p, alt: "(fehlt)", neu: kurz(neu[k]) });
      else if (!(k in neu)) liste.push({ pfad: p, alt: kurz(alt[k]), neu: "(fehlt)" });
      else abweichungen(alt[k], neu[k], p, liste);
    }
    return liste;
  }
  liste.push({ pfad: pfad || "(Wurzel)", alt: kurz(alt), neu: kurz(neu) });
  return liste;
}

/** Relative Änderung für Zahlen (für den Diff-Bericht), sonst null. */
export function relativ(altText, neuText) {
  const a = Number(altText);
  const n = Number(neuText);
  if (!Number.isFinite(a) || !Number.isFinite(n) || a === 0) return null;
  return (n - a) / Math.abs(a);
}
// test/hilfen/aufloesen.mjs – Auflöse-Hook zu registrieren.mjs (nur für Tests)
import { existsSync, statSync } from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const WURZEL = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const SRC = path.join(WURZEL, "src");
const klein = (p) => (process.platform === "win32" ? p.toLowerCase() : p);
const imProjekt = (p) => klein(p).startsWith(klein(WURZEL)) && !p.includes(`${path.sep}node_modules${path.sep}`);

function kandidat(basis) {
  for (const p of [basis, `${basis}.js`, `${basis}.mjs`, path.join(basis, "index.js")]) {
    if (existsSync(p) && statSync(p).isFile()) return p;
  }
  return null;
}

export async function resolve(spezifizierer, kontext, weiter) {
  let basis = null;
  if (spezifizierer.startsWith("@/")) basis = path.join(SRC, spezifizierer.slice(2));
