      (f) =>
        (!l || f.land === l || (mitDach && l !== "DACH" && f.land === "DACH")) &&
        (!klasse || f.klasse === klasse) &&
        (!praefix || f.id.startsWith(praefix)) &&
        (!status || f.status === status)
    );
  }

  /** Alle Fakten aller Module */
