// src/components/Rechner/LaenderSperre.js
//
// Länder-Sperre (Masterplan S1, Welle 1 Paket E): Für Österreich und die Schweiz
// zeigen die Rechner keine Euro-, EEG-, GAP- oder Pachtwerte, solange die
// Länderlogik nicht fachlich geprüft ist. Text und Titel kommen aus markt.js
// (laenderSperre), damit alle Rechner dieselbe Aussage machen.
//
// <LaenderSperre sperre={laenderSperre(land)} />            – Ergebnisbereich
// <SperrEingaben sperre={…}>{Länder-/Regionswahl}</SperrEingaben> – Eingabespalte

import { Clock } from "lucide-react";
import Button from "@/components/ui/Button";

export function LaenderSperre({ sperre, kontaktHref = "/kontakt" }) {
  if (!sperre) return null;
  return (
    <div role="status" className="rounded-3xl bg-sand-50 p-6 ring-1 ring-ink-200/70 md:p-8" data-laender-sperre={sperre.land}>
      <p className="flex items-center gap-2 text-[13px] font-semibold uppercase tracking-[0.08em] text-ink-500">
        <Clock aria-hidden="true" className="h-4 w-4 text-navy-500" /> {sperre.land === "AT" ? "Österreich" : "Schweiz"}
      </p>
      <h3 className="mt-3 font-display text-[clamp(1.25rem,1.1rem+0.6vw,1.6rem)] font-extrabold leading-tight tracking-tight text-ink-900">{sperre.titel}</h3>
      <p className="mt-3 max-w-prose text-[15px] leading-relaxed text-ink-700">{sperre.text}</p>
      <div className="mt-5">
        <Button href={kontaktHref} pfeil>
          Vorhaben persönlich besprechen
        </Button>
      </div>
    </div>
  );
}

/** Eingabespalte bei gesperrtem Land: nur die Länder-/Regionswahl, damit man zurück nach Deutschland wechseln kann */
export function SperrEingaben({ children }) {
  return (
    <div className="space-y-4">
      {children}
      <p className="text-[13px] leading-relaxed text-ink-500">Wählen Sie eine Region in Deutschland, um die Rechnung zu sehen.</p>
    </div>
  );
}
import { cn } from "./cn";

/**
 * Badge / Status-Chip des Design-Systems 2.0.
 *
 * ton:   neutral | info | success (= ok) | warn | danger | marke | navy | dunkel | glas
 * groesse: sm | md
 * punkt:   farbiger Statuspunkt davor; live = pulsierender Punkt (Live-Daten)
 * icon:    Lucide-Icon statt Punkt
 *
 * Text immer ≥ 4.5:1 auf dem Hintergrund (geprüft, siehe DESIGN.md).
 * Status nie nur über Farbe: Beschriftung ist Pflicht.
 */
export const BADGE_TOENE = {
  neutral: { flaeche: "bg-ink-100 text-ink-700 ring-ink-200", punkt: "bg-ink-400" },
  info: { flaeche: "bg-navy-50 text-navy-700 ring-navy-100", punkt: "bg-navy-500" },
  success: { flaeche: "bg-ov-50 text-ov-800 ring-ov-200", punkt: "bg-ov-500" },
  ok: { flaeche: "bg-ov-50 text-ov-800 ring-ov-200", punkt: "bg-ov-500" },
  warn: { flaeche: "bg-sun-50 text-sun-700 ring-sun-200", punkt: "bg-sun-500" },
  danger: { flaeche: "bg-danger-50 text-danger-700 ring-danger-200", punkt: "bg-danger-500" },
  marke: { flaeche: "bg-ov-600 text-white ring-ov-700/40", punkt: "bg-white" },
  navy: { flaeche: "bg-navy-700 text-white ring-navy-800", punkt: "bg-ov-300" },
  dunkel: { flaeche: "bg-white/10 text-white ring-white/15", punkt: "bg-ov-300" },
  glas: { flaeche: "ov-glass text-white ring-transparent", punkt: "bg-ov-300" },
};

export default function Badge({ ton = "neutral", groesse = "md", punkt = false, live = false, icon: Icon, className, children, ...rest }) {
  const t = BADGE_TOENE[ton] || BADGE_TOENE.neutral;
  return (
    <span
      className={cn(
        "inline-flex items-center whitespace-nowrap rounded-full font-semibold ring-1 ring-inset",
        groesse === "sm" ? "gap-1 px-2 py-0.5 text-[11.5px]" : "gap-1.5 px-2.5 py-1 text-[12px]",
        t.flaeche,
        className
      )}
      {...rest}
    >
      {Icon ? (
        <Icon aria-hidden="true" className={groesse === "sm" ? "h-3 w-3" : "h-3.5 w-3.5"} />
