  assert.equal(v.ok, true, v.fehler.join("\n"));
  assert.deepEqual(v.fehler, []);
});

test("Pflichtfelder: fehlende quelle, abruf, pruefer, klasse, land werden gemeldet", () => {
  for (const [feld, wert] of [
