  assert.equal(anzeigeStatus(gut(), "2027-01-02"), "abgelaufen");
  assert.equal(anzeigeStatus({ ...gut(), status: "zu_pruefen" }, "2026-10-03"), "zu_pruefen");
  assert.equal(HINWEIS_ABGELAUFEN, "Stand abgelaufen, wird geprüft");
});

test("Datumshilfen", () => {
