const testRegister = () =>
  erstelleRegister([
    {
      name: "a",
      land: "DE",
      fakten: [
        { ...basis, id: "t.wert", land: "DE", wert: 1 },
        { ...basis, id: "t.technik", land: "DACH", wert: { min: 1, max: 2 } },
      ],
      quellen: { allgemein: [{ titel: "Q", url: "https://example.org/q" }] },
    },
    [
